function HandleInstaller($p){try{if($p.MainWindowHandle -eq 0){return};$title=''+$p.MainWindowTitle;if($title -notmatch '(?i)setup|select setup language|install|download failed|cannot connect|exit setup'){return};$root=[System.Windows.Automation.AutomationElement]::FromHandle([IntPtr]$p.MainWindowHandle);if(!$root){return};$all=$title+' | '+(Get-Text $root);$nodes=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);if($all -match '(?i)(Exit Setup\?|Setup is not complete|If you exit now|terminate setup)'){foreach($n in @($nodes)){$nm='';try{$nm=(''+$n.Current.Name).Trim()}catch{};if($nm -match '(?i)^&?No$'){try{[Microsoft.VisualBasic.Interaction]::AppActivate($p.Id)|Out-Null;Start-Sleep -Milliseconds 80}catch{};Click $n ('block-exit-setup '+$nm+' title='+$title)|Out-Null;return}};Log ('blocked exit setup title='+$title);return};$normal=($all -match '(?i)(Welcome to the|License Agreement|Information|Select Destination Location|Select Start Menu Folder|Select Additional Tasks|Ready to Install|Setup will install)');if(!$normal -and $all -match '(?i)(Downloading additional files|Download failed|Cannot connect|certificate is invalid|SSL|TLS|revocation|connection failed|unable to download|timed out)'){foreach($want in @('^Skip$','^No$','^OK$','^Continue$','^Ignore$')){foreach($n in @($nodes)){$nm='';try{$nm=(''+$n.Current.Name).Trim()}catch{};if($nm -match ('(?i)'+$want) -and $nm -notmatch '(?i)Abort|Retry|Details|Back|Cancel'){try{[Microsoft.VisualBasic.Interaction]::AppActivate($p.Id)|Out-Null;Start-Sleep -Milliseconds 80}catch{};if(Click $n ('optional-failure '+$nm+' title='+$title)){return}}}}};foreach($n in @($nodes)){$nm='';try{$nm=(''+$n.Current.Name).Trim()}catch{};if($nm.Length -lt 200 -and $nm -match '(?i)(DirectX|Visual C\+\+|Redistributable|additional files|download|bonus|soundtrack|video)' -and $nm -notmatch '(?i)^Next|Install|Finish|OK|Yes|Retry|Details$'){ToggleOff $n ($nm+' title='+$title)|Out-Null}};foreach($want in @('^OK$','^Next\s*>?$','^Install$','^Finish$','^Close$')){foreach($n in @($nodes)){$nm='';try{$nm=(''+$n.Current.Name).Trim()}catch{};if($nm -match ('(?i)'+$want) -and $nm -notmatch '(?i)Cancel|Abort|Decline|Back|Browse|Retry|Details'){try{[Microsoft.VisualBasic.Interaction]::AppActivate($p.Id)|Out-Null;Start-Sleep -Milliseconds 80}catch{};if(Click $n ($nm+' title='+$title)){return}}}};if($title -match '(?i)select setup language'){try{[Microsoft.VisualBasic.Interaction]::AppActivate($p.Id)|Out-Null;Start-Sleep -Milliseconds 120;[System.Windows.Forms.SendKeys]::SendWait('{ENTER}');Log ('sendkeys language-enter title='+$title+' pid='+$p.Id)}catch{}}}catch{Log ('installer handler failed '+$_.Exception.Message)}}
function GuardQuickSfv{try{$now=Get-Date;foreach($p in @(Get-CimInstance Win32_Process -Filter "Name='QuickSFV.EXE'" -ErrorAction SilentlyContinue)){$age=0;try{$age=($now-([Management.ManagementDateTimeConverter]::ToDateTime($p.CreationDate))).TotalSeconds}catch{};if($age -ge 45){try{Stop-Process -Id ([int]$p.ProcessId) -Force -ErrorAction SilentlyContinue;Log ('killed optional QuickSFV checker pid='+$p.ProcessId+' age='+[int]$age)}catch{}}}}catch{Log ('QuickSFV guard failed '+$_.Exception.Message)}}
Log 'V5 started: robust dialog clicker, optional-online-failure skip, destination guard, QuickSFV skip'
 $endsAt = (Get-Date).AddMinutes($LifetimeMinutes)
while((Get-Date) -lt $endsAt){try{GuardQuickSfv;foreach($p in @(Get-Process -ErrorAction SilentlyContinue|Where-Object{$_.ProcessName -match '^(setup|setup\.tmp)$' -and $_.MainWindowHandle -ne 0})){HandleInstaller $p}}catch{Log ('loop warning '+$_.Exception.Message)};Start-Sleep -Milliseconds 500}
} finally { try { $mutex.ReleaseMutex() } catch {}; try { $mutex.Dispose() } catch {} }
'@
    $code = $code.Replace('$LifetimeMinutes', [string]$LifetimeMinutes)
    $childPath = Join-Path $scriptDir 'AfitgirlInstallerAutoClickerV5.ps1'
    [IO.File]::WriteAllText($childPath, $code, [Text.Encoding]::UTF8)
    $process = Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',$childPath) -WindowStyle Hidden -PassThru -ErrorAction Stop
    Write-Host ("AFITGIRL_AUTOCLICKER_OK pid={0} script={1} lifetime_minutes={2}; AHK task/script refreshed" -f $process.Id, $childPath, $LifetimeMinutes) -ForegroundColor Green
    return [pscustomobject]@{ ProcessId = $process.Id; ScriptPath = $childPath; LifetimeMinutes = $LifetimeMinutes }
}

if ($MyInvocation.InvocationName -ne '.') {
    & 'Start-AfitgirlInstallerAutoClicker' @args
}
